   "goal": "I can tell what someone can see and what they know.",
   "slpNotes": "Key idea: people can only know what they saw or heard. \"She ignored me\" and \"She didn’t see me\" are two meanings of the same moment. Push for the meaning that fits the clues.\n\nAccept reasonable interpretations supported by the clues. Faces, bodies, and tone are possible clues, not proof. Asking the person is always a valid strategy.\n\nVideo search ideas: perspective taking what can they see video; visual perspective taking activity middle school",
