   "goal": "I can use the place and what is happening to figure out what words mean.",
   "slpNotes": "Same words, different place, different meaning. Ask \"Where are they? What just happened?\" before \"What does it mean?\" Slang is great here; let the student teach you some.\n\nAccept reasonable interpretations supported by the clues. Faces, bodies, and tone are possible clues, not proof. Asking the person is always a valid strategy.\n\nVideo search ideas: multiple meaning words in context video; slang words meaning depends on context",
