   "skill": "Noticing clues that don’t match",
   "goal": "I can notice when words and other clues don’t match.",
   "slpNotes": "When words and face don’t match, the face and body often tell more. But don’t force it: people also hide feelings on purpose. The kind move is a gentle check-in, not \"You’re lying.\"\n\nAccept reasonable interpretations supported by the clues. Faces, bodies, and tone are possible clues, not proof. Asking the person is always a valid strategy.\n\nVideo search ideas: facial expression does not match words video; body language vs words mismatch",
