   "slpNotes": "This unit is about reading between the lines. Here the clue is what a person does NOT say: a very short answer, a changed subject, or news they usually share but skip. Stress that a missing piece is a clue, not proof. Model kind responses: let it go, or check in gently without pushing.\n\nAccept reasonable interpretations supported by the clues. Faces, bodies, and tone are possible clues, not proof. Asking the person is always a valid strategy.",
