   "slpNotes": "People show what they want through actions (where they look, stand, or wait) and words (hints, questions). Guide students to name the action clue, then the word clue, then the want. Point out that people may want more than one thing (e.g., the game AND to feel included). Checking with a kind question is always fine.\n\nAccept reasonable interpretations supported by the clues. Faces, bodies, and tone are possible clues, not proof. Asking the person is always a valid strategy.",
