   "id": "scope-21",
   "number": 21,
   "title": "Thinking they know (but they don't)",
   "unit": "SCOPE Unit 3: Reading Between the Lines",
   "program": "SCOPE",
   "skill": "Understanding knowledge gaps and false beliefs",
   "goal": "I can tell when someone doesn’t know what I know.",
   "slpNotes": "People act on what they believe, even when it is old or wrong. Students may also assume others know what they know (“the spot,” “that show”). Use “Who saw it? Who heard it?” to track knowledge. The Engage step is giving the missing information kindly, or adding background when you talk.\n\nAccept reasonable interpretations supported by the clues. Faces, bodies, and tone are possible clues, not proof. Asking the person is always a valid strategy.",
