   "skill": "Listening and asking follow-up questions",
   "goal": "I can listen to a story and ask a good follow-up question.",
   "slpNotes": "Teach visible listening signs (turning toward the speaker, nodding, short comments like \"No way\"), follow-up questions that stay on their topic (who, what, how, then what), and waiting before switching to yourself. Some students listen best without eye contact, so accept turning toward the speaker or other signs of attention. Practice \"one more question\" before any \"me too.\"\n\nAccept reasonable interpretations supported by the clues. Faces, bodies, and tone are possible clues, not proof. Asking the person is always a valid strategy.",
