   "skill": "Hearing opinions said as facts",
   "goal": "I can tell when an opinion is said like a fact.",
   "slpNotes": "People often state opinions as if they were facts (\"Math is pointless.\" \"That movie is boring.\"). This can make listeners feel told they are wrong. Teach the P-step question: \"Is this a fact, or what they think?\" and the E-step move: answer calmly with your own view instead of arguing. Point out there is no need to win an opinion.\n\nAccept reasonable interpretations supported by the clues. Faces, bodies, and tone are possible clues, not proof. Asking the person is always a valid strategy.",
