   "slpNotes": "Two people can have different opinions and neither is wrong. Practice kind responses: \"Cool, I see it differently.\" and \"What do you like about it?\" Then contrast with a fact disagreement: if it can be checked, look it up or ask the teacher together instead of fighting. Role-play both sides.\n\nAccept reasonable interpretations supported by the clues. Faces, bodies, and tone are possible clues, not proof. Asking the person is always a valid strategy.",
   "standards": [
    "C.6",
    "C.7"
   ],
