   "slpNotes": "Many tasks have more than one path to a correct result: math strategies, packing a bag, studying, warming up, building a project. Point out that people learned different ways from different teachers, families, or practice, so the Others know step matters: Omar knows a way Lily was never taught. Practice swapping “You're doing it wrong” for “Show me your way?” Note the difference between the answer (which can be wrong) and the method (which can just be different).\n\nAccept reasonable interpretations supported by the clues. Faces, bodies, and tone are possible clues, not proof. Asking the person is always a valid strategy.\n\nVideo search ideas: more than one way to solve a problem kids; flexible thinking different ways social skills",
