   "goal": "I can use clues to tell if someone is being sarcastic.",
   "slpNotes": "Sarcasm is when the words say one thing but the person means the opposite. Teach three clues: the words don’t match what happened, the voice is flat or over the top, and the face may show an eye roll or smirk. YOU say each line aloud; hold Peek to see how. Pair sarcastic and sincere versions so the student hears the difference.\n\nAccept reasonable interpretations supported by the clues. Faces, bodies, and tone are possible clues, not proof. Asking the person is always a valid strategy.",
