   "skill": "Responding to friendly and unkind sarcasm",
   "goal": "I can choose a good way to answer sarcasm.",
   "slpNotes": "Sarcasm can be friendly teasing between friends or a put-down. Clues: who said it, their face, whether others laugh with you or at you, and how it feels. Friendly: laugh along or joke back gently. Unkind: calmly say “That wasn’t nice” or walk away, and tell an adult if it keeps happening. If unsure, ask “Are you kidding?” Also talk about thinking before using sarcasm, since not everyone gets it.\n\nAccept reasonable interpretations supported by the clues. Faces, bodies, and tone are possible clues, not proof. Asking the person is always a valid strategy.",
