   "skill": "Deciding what is worth arguing about",
   "goal": "I can tell a small problem from a big one.",
   "slpNotes": "Source: Degree of Importance. This unit teaches students to \"pick their battles.\" Introduce a simple 1–10 scale: small things (the last French fry, who goes first, which seat) are not worth an argument; big things (cheating, lying, being mean to someone) are worth speaking up about. Have the student rate each item out loud before choosing, and point out that the same item can matter more to one person than another.\n\nAccept reasonable interpretations supported by the clues. Faces, bodies, and tone are possible clues, not proof. Asking the person is always a valid strategy.",
