   "id": "scope-58",
   "number": 58,
   "title": "Letting it go",
   "unit": "SCOPE Unit 10: Interpersonal Negotiation",
   "program": "SCOPE",
   "skill": "Knowing when to give in to keep a friendship",
   "goal": "I can let small things go to keep a friend.",
   "slpNotes": "Source: Acquiescence. Not every disagreement needs a deal. Teach three steps: ask “How much does this matter to me?”; if small, let it go (“Sure, you pick”); if medium, compromise; if big (it really matters to you, or it is about safety or what you believe is right), don’t give in—talk it out. Stress that letting it go is a choice, not losing.\n\nAccept reasonable interpretations supported by the clues. Faces, bodies, and tone are possible clues, not proof. Asking the person is always a valid strategy.",
