   "goal": "I can invite a friend to try something without pushing.",
   "slpNotes": "Source: Persuasion (the skateboarding example). When you love something, it is easy to push a friend too hard. Teach the difference between pushing (“Just do it!”) and inviting a small first step that fits the friend’s comfort (watch first, stand on the board on the grass). Spend time on the O step: listen to the friend’s worry. A “no” is respected.\n\nAccept reasonable interpretations supported by the clues. Faces, bodies, and tone are possible clues, not proof. Asking the person is always a valid strategy.",
